window.RP_SESSION={"id":"S-4541caf170ee","messages":[{"id":"RP-II-0203102","time":"2026-09-23T01:10:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"슥 삭 슥 삭","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203103","time":"2026-09-23T01:12:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“클레이 님, 부탁드립니다.”\n\n[ 그럼요, 베에에… ]\n\n“…굳이 물을 뱉는 듯한 시늉을 하실 필요는 없습니다…”\n\n[ 후후, 장난이에요 장난. ]","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203104","time":"2026-09-23T01:12:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"슥 삭 슥 삭","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203105","time":"2026-09-23T01:13:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”참, 그러고 보니 클레이 님. 어젯날 저녁에 베어 님과 허그 님께서 전에 부탁드린 물건을 구입하여 가져다 주셨습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203106","time":"2026-09-23T01:15:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”잉크부터 펜, 양피지까지 전부 제가 드렸던 물건의 값을 넘어선 좋은 물건들이었었죠.\n그 위엔 허그 님께서 어떤 글을 남는 양피지에\n적어주신 것 같았습니다만…“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203107","time":"2026-09-23T01:16:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”베어 님과 허그 님께서 저를 걱정하고 계신다는 듯한 의도의 몇몇 단어들 빼고는 죄송하게도 알아볼 수 없었습니다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203108","time":"2026-09-23T01:19:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…음, 길드원 분들께 부끄러운 모습을 보여드렸던 것 같군요. 클레이 님께도 마찬가지입니다, 이만 슬슬 몸을 움직일 때가 돌아온 듯 싶습니다.”","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203109","time":"2026-09-23T01:21:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…이전에 봐둔 곳이 몇군데 있었으니, 그곳 부터 다시금 밟아가며 펜을 쥐어버릇 해야겠군요. 내일은 일찍 일어나야겠습니다, 클레이 님.“","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203110","time":"2026-09-23T01:21:00+09:00","room":"RP II","name":"오즈발드 / 클레이","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d40bea4fdee0"]},{"id":"RP-II-0203111","time":"2026-09-23T01:21:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
